# A minimal real-time serving endpoint + the autoscaling decision.
model = load_model_to_gpu()  # done ONCE at startup, not per request

def handle_request(prompt):
    return model.generate(prompt)

def should_scale(queue_depth, replicas, high=20, low=5):
    # TODO: return "up", "down", or "hold" based on queue_depth
    if queue_depth > high:
        return "up"
    if queue_depth < low and replicas > 1:
        return "down"
    return "hold"
